    border: '1px solid #e2e8f0',
    boxShadow: '0 2px 6px rgba(0,0,0,0.02)'
  },
  statLabel: {
    margin: 0,
    fontSize: '11px',
    color: '#64748b',
    fontWeight: 'bold'
  },
  statValue: {
    margin: '3px 0 0 0',
    fontSize: '17px',
    fontWeight: 'bold'
  },
  subjectPillBtn: {
    padding: '5px 14px',
    borderRadius: '16px',
    fontSize: '12px',
    fontWeight: 'bold',
    cursor: 'pointer',
    transition: 'all 0.2s'
  },
  classBadge: {
    backgroundColor: '#f0fdf4',
    border: '1px solid #bbf7d0',
    borderRadius: '6px',
    padding: '4px',
    fontSize: '10.5px',
    color: '#145c2e'
  },
  primaryBtn: {
    backgroundColor: '#145c2e',
    color: 'white',
    border: 'none',
    padding: '7px 14px',
    borderRadius: '6px',
    cursor: 'pointer',
    fontWeight: 'bold',
    textDecoration: 'none',
    display: 'inline-block',
    textAlign: 'center',
    fontSize: '12.5px'
  },
  subjectBadge: {
    backgroundColor: '#f0fdf4',
    color: '#145c2e',
    border: '1px solid #bbf7d0',
    padding: '2px 8px',
    borderRadius: '10px',
    fontSize: '11px',
    fontWeight: 'bold'
  },
  materialCard: {
    backgroundColor: '#ffffff',
    border: '1px solid #e2e8f0',
    borderRadius: '12px',
    padding: '14px',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
    boxShadow: '0 2px 4px rgba(0,0,0,0.02)'
  },
  actionBtn: {
    width: '100%',
    padding: '8px 10px',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontWeight: 'bold',
    fontSize: '12px',
    textDecoration: 'none',
    display: 'block',
    textAlign: 'center'
  },
  filterTab: {
    border: 'none',
    padding: '5px 12px',
    borderRadius: '16px',
    fontSize: '11.5px',
    fontWeight: 'bold',
    cursor: 'pointer',
    transition: 'all 0.2s'
  },
  modalOverlay: {
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    backgroundColor: 'rgba(0,0,0,0.6)',
    display: 'flex',
