    border: '1px solid #cbd5e1',
    outline: 'none',
    fontSize: '12.5px',
    backgroundColor: '#fff',
    width: '100%',
    boxSizing: 'border-box'
  },
  label: {
    fontSize: '12px',
    fontWeight: 'bold',
    color: '#334155',
    marginBottom: '3px',
    display: 'block'
  },
  activityCardClean: {
    backgroundColor: '#ffffff',
    border: '1px solid #e2e8f0',
    borderLeft: '4px solid #145c2e',
