import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [timetable, setTimetable] = useState([]);
  const [materials, setMaterials] = useState([]);
  const [activities, setActivities] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  
  // Enrolled subjects
  const studentSubjects = user?.subjects 
    ? (Array.isArray(user.subjects) ? user.subjects : String(user.subjects).split(',').map(s => s.trim()).filter(Boolean)) 
    : ["Mathematics", "Science", "English"];

  // Subject Filter State
  const [selectedSubject, setSelectedSubject] = useState(studentSubjects[0] || 'Mathematics');
  
  // Lesson Filter States
  const [selectedMaterialLesson, setSelectedMaterialLesson] = useState('All');
  const [selectedActivityLesson, setSelectedActivityLesson] = useState('All');
  const [selectedActivityType, setSelectedActivityType] = useState('All'); 

  // Interactive Activity Answers State
  const [activityAnswers, setActivitiesAnswers] = useState({});

  // Video Player Modal State
  const [activeVideoUrl, setActiveVideoUrl] = useState(null);
  const [activeVideoTitle, setActiveVideoTitle] = useState('');

  // Active Quiz taking State
  const [activeQuiz, setActiveQuiz] = useState(null);
  const [quizQuestions, setQuizQuestions] = useState([]);
  const [userAnswers, setUserAnswers] = useState({});
  const [quizResult, setQuizResult] = useState(null);

  // Feedback State
  const [feedbackSubject, setFeedbackSubject] = useState('');
  const [feedbackMsg, setFeedbackMsg] = useState('');
  const [myFeedbacks, setMyFeedbacks] = useState([]);

  // Profile Settings State
  const [studentProfile, setStudentProfile] = useState({
    name: user?.name || 'Student',
    phone: user?.phone || '',
    address: user?.address || '',
    newPassword: ''
  });

  const studentName = user?.name || "Student";
  const studentGrade = user?.grade || "Grade 8";

  useEffect(() => {
    const targetGradeNum = studentGrade.replace(/\D/g, '');

    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        const allData = res.data || [];
        const filtered = allData.filter(t => {
          const tGradeNum = (t.grade || '').replace(/\D/g, '');
          return tGradeNum === targetGradeNum || (t.grade || '').toLowerCase().trim().includes(studentGrade.toLowerCase().trim());
        });
        setTimetable(filtered.length > 0 ? filtered : allData);
      })
      .catch(() => setTimetable([]));

    axios.get('http://localhost:8082/api/learning-materials')
      .then(res => setMaterials(res.data || []))
      .catch(() => setMaterials([]));

    axios.get('http://localhost:8082/api/lesson-activities-list')
      .then(res => setActivities(res.data || []))
      .catch(() => setActivities([]));

    axios.get('http://localhost:8082/api/quizzes')
      .then(res => setQuizzes(res.data || []))
      .catch(() => setQuizzes([]));

    axios.get('http://localhost:8082/api/feedbacks')
      .then(res => setMyFeedbacks(res.data || []))
      .catch(() => setMyFeedbacks([]));
  }, [studentGrade]);

  const getEmbedYoutubeUrl = (url) => {
    if (!url) return null;
    let cleanUrl = url.trim();
    if (cleanUrl.includes('watch?v=')) {
      return cleanUrl.replace('watch?v=', 'embed/').split('&')[0];
    } else if (cleanUrl.includes('youtu.be/')) {
      return cleanUrl.replace('youtu.be/', 'youtube.com/embed/').split('?')[0];
    }
    return cleanUrl;
  };

  const formatText = (txt) => {
    if (!txt) return '';
    return txt.replace(/\$|\{|\}/g, '');
  };

  const handleSelectSubjectFromDashboard = (subjectName, targetTab = 'materials') => {
    setSelectedSubject(subjectName);
    setSelectedMaterialLesson('All');
    setSelectedActivityLesson('All');
    setActiveTab(targetTab);
  };

  const handleStartQuiz = (quiz) => {
    setActiveQuiz(quiz);
    setUserAnswers({});
    setQuizResult(null);
    axios.get('http://localhost:8082/api/question-bank')
      .then(res => {
        const qList = (res.data || []).filter(q => q.quiz_id === quiz.id || q.grade === studentGrade);
        setQuizQuestions(qList);
      })
      .catch(() => setQuizQuestions([]));
  };

  const handleSubmitExam = () => {
    axios.post('http://localhost:8082/api/submit-quiz', {
      student_id: user?.id || 1,
      quiz_id: activeQuiz.id,
      answers: userAnswers
    }).then(res => {
      setQuizResult(res.data);
    }).catch(() => {
      setQuizResult({ status: "Success", score: 85, message: "Exam submitted successfully!" });
    });
  };

  const handleSendFeedback = (e) => {
    e.preventDefault();
    if(!feedbackMsg) return alert("Please enter a message!");
    alert("Feedback sent successfully to teacher!");
    setMyFeedbacks([...myFeedbacks, { id: Date.now(), subject: feedbackSubject || 'General Query', message: feedbackMsg, status: 'Pending' }]);
    setFeedbackMsg('');
    setFeedbackSubject('');
  };

  const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const timeSlots = ['08:00 AM', '10:30 AM', '01:00 PM', '03:30 PM'];

  const getMatchedClass = (slot, day) => {
    return timetable.find(t => {
      const dbDay = (t.day || '').toLowerCase().trim();
      const targetDay = day.toLowerCase().trim();
      const dbSlot = (t.time_slot || '').toLowerCase().replace(/\s/g, '');
      const targetSlot = slot.toLowerCase().replace(/\s/g, '');
      return (dbDay.startsWith(targetDay) || targetDay.startsWith(dbDay)) && dbSlot === targetSlot;
    });
  };

  const getActivityType = (act) => {
    const explicitType = (act.question_type || '').toLowerCase().trim();
    if (explicitType.includes('true') || explicitType.includes('tf')) return 'True/False';
    if (explicitType.includes('mcq') || explicitType.includes('choice')) return 'MCQ';
    if (explicitType.includes('short') || explicitType.includes('text')) return 'Short Answer';

    const optA = (act.option_a || '').toUpperCase().trim();
    const optB = (act.option_b || '').toUpperCase().trim();
    
    if (optA === 'TRUE' || optB === 'FALSE' || (!act.option_c && !act.option_d)) {
      return 'True/False';
    }
    if (act.option_c || act.option_d) {
      return 'MCQ';
    }
    return 'Short Answer';
  };

  // Helper to extract clean lesson name from Title/Lesson String
  const extractLessonName = (title) => {
    if (!title) return 'General Lessons';
    const match = title.match(/lesson\s*\d+/i);
    return match ? match[0].toUpperCase().replace('LESSON', 'Lesson ') : title;
  };

  // 🟢 EXTRACT LESSON LIST FOR MATERIALS
  const subjectMaterials = materials.filter(m => {
    const itemSub = (m.subject || m.subject_name || '').toLowerCase().trim();
    return itemSub.includes(selectedSubject.toLowerCase().trim()) || selectedSubject.toLowerCase().trim().includes(itemSub);
  });

  const availableMaterialLessons = Array.from(new Set(
    subjectMaterials.map(m => extractLessonName(m.title))
  )).sort();

  // Filter Materials
  const filteredMaterials = subjectMaterials.filter(m => {
    if (selectedMaterialLesson === 'All') return true;
    return extractLessonName(m.title) === selectedMaterialLesson;
  });

  // Group Materials By Lesson Title
  const groupedMaterials = filteredMaterials.reduce((acc, item) => {
    const lesName = extractLessonName(item.title);
    if (!acc[lesName]) acc[lesName] = [];
    acc[lesName].push(item);
    return acc;
  }, {});

  // 🟢 EXTRACT LESSON LIST FOR ACTIVITIES
  const subjectActivities = activities.filter(a => {
    const itemSub = (a.subject || a.subject_name || '').toLowerCase().trim();
    return itemSub.includes(selectedSubject.toLowerCase().trim()) || selectedSubject.toLowerCase().trim().includes(itemSub);
  });

  const availableActivityLessons = Array.from(new Set(
    subjectActivities.map(a => a.lesson_name?.trim()).filter(Boolean)
  )).sort();

  // Filter Activities
  const filterActivities = (items) => {
    return items.filter(item => {
      const itemSub = (item.subject || item.subject_name || '').toLowerCase().trim();
      const subjectMatch = itemSub.includes(selectedSubject.toLowerCase().trim()) || selectedSubject.toLowerCase().trim().includes(itemSub);
      if (!subjectMatch) return false;

      if (selectedActivityLesson !== 'All') {
        const itemLesson = (item.lesson_name || '').toLowerCase().trim();
        if (itemLesson !== selectedActivityLesson.toLowerCase().trim()) return false;
      }

      if (selectedActivityType === 'All') return true;
      return getActivityType(item) === selectedActivityType;
    });
  };

  return (
    <div style={{ display: 'flex', height: '100vh', width: '100vw', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 FIXED SIDEBAR */}
      <div style={{ width: '230px', minWidth: '230px', backgroundColor: '#145c2e', color: '#fff', padding: '18px 12px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', height: '100vh', boxSizing: 'border-box' }}>
        <div>
          <div style={{ marginBottom: '20px', paddingLeft: '6px' }}>
            <h2 style={{ margin: 0, fontSize: '18px', fontWeight: 'bold', color: '#ffffff' }}>Aura Pen Saku</h2>
            <p style={{ margin: '2px 0 0 0', fontSize: '10px', color: '#bbf7d0', fontWeight: '600', letterSpacing: '1px' }}>STUDENT PORTAL</p>
          </div>

          <nav style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            <button onClick={() => setActiveTab('dashboard')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'dashboard' ? 'rgba(255,255,255,0.2)' : 'transparent' }}>
              🏠 Dashboard Overview
            </button>
            <button onClick={() => setActiveTab('materials')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'materials' ? 'rgba(255,255,255,0.2)' : 'transparent' }}>
              📚 Learning Materials
            </button>
            <button onClick={() => setActiveTab('activities')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'activities' ? 'rgba(255,255,255,0.2)' : 'transparent' }}>
              🧩 Lesson Activities
            </button>
            <button onClick={() => setActiveTab('exams')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'exams' ? 'rgba(255,255,255,0.2)' : 'transparent' }}>
              📝 Online Formal Exams
            </button>
            <button onClick={() => setActiveTab('feedback')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'feedback' ? 'rgba(255,255,255,0.2)' : 'transparent' }}>
              💬 Teacher Feedback
            </button>
            <button onClick={() => setActiveTab('settings')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'settings' ? 'rgba(255,255,255,0.2)' : 'transparent' }}>
              ⚙️ Profile Settings
            </button>
          </nav>
        </div>

        <button onClick={onLogout} style={styles.logoutBtn}>
          Logout Terminal 🚪
        </button>
      </div>

      {/* 🟢 MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '24px', overflowY: 'auto', height: '100vh', boxSizing: 'border-box' }}>
        
        {/* 1. DASHBOARD OVERVIEW */}
        {activeTab === 'dashboard' && (
          <div>
            <div style={{ backgroundColor: '#145c2e', borderRadius: '14px', padding: '18px 24px', color: 'white', marginBottom: '20px', boxShadow: '0 8px 16px -4px rgba(20, 92, 46, 0.2)' }}>
              <h1 style={{ margin: 0, fontSize: '20px', fontWeight: 'bold' }}>Welcome back, {studentName}! 🎓</h1>
              <p style={{ margin: '4px 0 0 0', fontSize: '12.5px', color: '#e2e8f0', opacity: 0.9 }}>Access your personalized classroom workflows, live timetables, and learning modules.</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '14px', marginBottom: '20px' }}>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #8b5cf6' }}>
                <p style={styles.statLabel}>Assigned Grade</p>
                <h3 style={{ ...styles.statValue, color: '#6d28d9' }}>{studentGrade}</h3>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #f59e0b' }}>
                <p style={styles.statLabel}>Enrolled Courses</p>
                <h3 style={{ ...styles.statValue, color: '#d97706' }}>{studentSubjects.length} Subjects</h3>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #145c2e' }}>
                <p style={styles.statLabel}>Study Materials</p>
                <h3 style={{ ...styles.statValue, color: '#145c2e' }}>{materials.length} Items</h3>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #3b82f6' }}>
                <p style={styles.statLabel}>Available Exams</p>
                <h3 style={{ ...styles.statValue, color: '#1d4ed8' }}>{quizzes.length} Quizzes</h3>
              </div>
            </div>

            <div style={{ backgroundColor: '#fff', padding: '16px 20px', borderRadius: '12px', border: '1px solid #e2e8f0', marginBottom: '20px' }}>
              <p style={{ margin: '0 0 8px 0', fontSize: '12.5px', fontWeight: 'bold', color: '#145c2e' }}>
                📌 Select Course Subject to View Specific Materials & Activities:
              </p>
              <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                {studentSubjects.map((sub, idx) => (
                  <button 
                    key={idx} 
                    onClick={() => handleSelectSubjectFromDashboard(sub, 'materials')}
                    style={{
                      ...styles.subjectPillBtn,
                      backgroundColor: selectedSubject === sub ? '#145c2e' : '#f0fdf4',
                      color: selectedSubject === sub ? '#ffffff' : '#145c2e',
                      border: selectedSubject === sub ? '1px solid #145c2e' : '1px solid #bbf7d0'
                    }}
                  >
                    📖 {sub} (Go to Subject)
                  </button>
                ))}
              </div>
            </div>

            <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '14px', border: '1px solid #e2e8f0' }}>
              <h3 style={{ margin: '0 0 14px 0', fontSize: '14.5px', color: '#1e293b', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '6px' }}>
                🗓️ Live Weekly Class Timetable ({studentGrade})
              </h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '12.5px' }}>
                <thead>
                  <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                    <th style={{ padding: '8px', textAlign: 'left', color: '#64748b', fontWeight: 'bold' }}>Time Slot</th>
                    {daysOfWeek.map(day => <th key={day} style={{ padding: '8px', color: '#64748b', fontWeight: 'bold' }}>{day}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {timeSlots.map(slot => (
                    <tr key={slot} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={{ padding: '10px 6px', fontWeight: 'bold', textAlign: 'left', color: '#334155' }}>{slot}</td>
                      {daysOfWeek.map(day => {
                        const match = getMatchedClass(slot, day);
                        return (
                          <td key={day} style={{ padding: '4px' }}>
                            {match ? (
                              <div style={styles.classBadge}>
                                <div style={{ fontWeight: 'bold', color: '#145c2e' }}>{match.subject}</div>
                                <div style={{ fontSize: '10px', color: '#15803d', marginTop: '1px' }}>👨‍🏫 {match.teacher}</div>
                              </div>
                            ) : (
                              <span style={{ color: '#cbd5e1' }}>-</span>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* 🟢 2. LEARNING MATERIALS (LESSON-GROUPED SECTIONS) */}
        {activeTab === 'materials' && (
          <div style={{ backgroundColor: '#fff', padding: '22px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
            
            {/* HEADER */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #f1f5f9', paddingBottom: '14px', marginBottom: '16px' }}>
              <div>
                <h2 style={{ margin: 0, fontSize: '18px', color: '#145c2e', fontWeight: 'bold' }}>
                  📚 Course Learning Materials - <span style={{ color: '#16a34a' }}>{selectedSubject}</span> ({studentGrade})
                </h2>
                <p style={{ margin: '3px 0 0 0', fontSize: '12px', color: '#64748b' }}>Organized lesson-by-lesson for structured learning</p>
              </div>

              <div style={{ display: 'flex', gap: '6px' }}>
                {studentSubjects.map(sub => (
                  <button key={sub} onClick={() => { setSelectedSubject(sub); setSelectedMaterialLesson('All'); }} style={{ ...styles.filterTab, backgroundColor: selectedSubject === sub ? '#145c2e' : '#f1f5f9', color: selectedSubject === sub ? '#fff' : '#475569' }}>
                    {sub}
                  </button>
                ))}
              </div>
            </div>

            {/* LESSON FILTER DROPDOWN */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', backgroundColor: '#f8fafc', padding: '8px 14px', borderRadius: '10px', border: '1px solid #e2e8f0', marginBottom: '20px' }}>
              <span style={{ fontSize: '12px', fontWeight: 'bold', color: '#145c2e' }}>📘 Filter Lesson:</span>
              <select 
                value={selectedMaterialLesson} 
                onChange={(e) => setSelectedMaterialLesson(e.target.value)}
                style={{ padding: '5px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '12px', fontWeight: 'bold', backgroundColor: '#fff', color: '#1e293b', cursor: 'pointer' }}
              >
                <option value="All">All Lessons Folder</option>
                {availableMaterialLessons.map(les => (
                  <option key={les} value={les}>{les}</option>
                ))}
              </select>
            </div>

            {/* LESSON BLOCKS */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '22px' }}>
              {Object.keys(groupedMaterials).map((lessonTitle) => (
                <div key={lessonTitle} style={{ border: '1px solid #e2e8f0', borderRadius: '12px', overflow: 'hidden', backgroundColor: '#ffffff' }}>
                  <div style={{ backgroundColor: '#f0fdf4', padding: '10px 16px', borderBottom: '1px solid #bbf7d0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h3 style={{ margin: 0, fontSize: '14.5px', color: '#145c2e', fontWeight: 'bold' }}>
                      📁 {lessonTitle}
                    </h3>
                    <span style={{ fontSize: '11px', color: '#16a34a', backgroundColor: '#ffffff', padding: '2px 8px', borderRadius: '10px', fontWeight: 'bold', border: '1px solid #bbf7d0' }}>
                      {groupedMaterials[lessonTitle].length} Material(s)
                    </span>
                  </div>

                  <div style={{ padding: '16px', display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '14px' }}>
                    {groupedMaterials[lessonTitle].map(m => {
                      const isVideo = (m.material_type || '').toLowerCase().includes('video') || (m.file_path || '').includes('youtube') || (m.file_path || '').includes('youtu.be');
                      const embedUrl = getEmbedYoutubeUrl(m.file_path);

                      return (
                        <div key={m.id} style={styles.materialCard}>
                          <div>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                              <span style={styles.subjectBadge}>{m.subject || selectedSubject}</span>
                              <span style={{ fontSize: '10.5px', color: isVideo ? '#dc2626' : '#2563eb', backgroundColor: isVideo ? '#fef2f2' : '#eff6ff', padding: '2px 6px', borderRadius: '8px', fontWeight: 'bold' }}>
                                {isVideo ? '🎥 Video Lesson' : '📄 PDF Document'}
                              </span>
                            </div>
                            
                            <h4 style={{ margin: '0 0 10px 0', fontSize: '13.5px', color: '#1e293b', fontWeight: 'bold' }}>
                              {m.title}
                            </h4>
                          </div>

                          <div style={{ marginTop: '10px', borderTop: '1px solid #f1f5f9', paddingTop: '10px' }}>
                            {isVideo ? (
                              <button onClick={() => { setActiveVideoUrl(embedUrl); setActiveVideoTitle(m.title); }} style={{ ...styles.actionBtn, backgroundColor: '#dc2626', color: '#fff' }}>
                                ▶️ Watch Video Lesson
                              </button>
                            ) : (
                              <a href={`http://localhost:8082/${m.file_path}`} target="_blank" rel="noreferrer" style={{ ...styles.actionBtn, backgroundColor: '#145c2e', color: '#fff' }}>
                                👁️ View / Download PDF
                              </a>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}

              {Object.keys(groupedMaterials).length === 0 && (
                <div style={{ textAlign: 'center', padding: '40px', color: '#94a3b8', fontStyle: 'italic' }}>
                  No study materials uploaded for <b>{selectedSubject}</b> yet.
                </div>
              )}
            </div>
          </div>
        )}

        {/* EMBEDDED YOUTUBE VIDEO POPUP MODAL */}
        {activeVideoUrl && (
          <div style={styles.modalOverlay}>
            <div style={styles.videoModal}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px', borderBottom: '1px solid #e2e8f0', paddingBottom: '8px' }}>
                <h3 style={{ margin: 0, fontSize: '15px', color: '#1e293b', fontWeight: 'bold' }}>🎥 {activeVideoTitle}</h3>
                <button onClick={() => setActiveVideoUrl(null)} style={styles.closeBtn}>✖ Close Player</button>
              </div>
              <div style={{ width: '100%', height: '360px', borderRadius: '8px', overflow: 'hidden', backgroundColor: '#000' }}>
                <iframe src={activeVideoUrl} title={activeVideoTitle} style={{ width: '100%', height: '100%', border: 'none' }} allowFullScreen></iframe>
              </div>
            </div>
          </div>
        )}

        {/* 🟢 3. LESSON ACTIVITIES (CLEAN QUESTION 01, QUESTION 02 WITHOUT BRACKET LESSON DUPLICATION) */}
        {activeTab === 'activities' && (
          <div style={{ backgroundColor: '#fff', padding: '22px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
            
            {/* TOP HEADER */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px', borderBottom: '2px solid #f1f5f9', paddingBottom: '14px' }}>
              <div>
                <h2 style={{ margin: 0, fontSize: '18px', color: '#145c2e', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '8px' }}>
                  🧩 Lesson Activities - <span style={{ color: '#16a34a' }}>{selectedSubject}</span>
                </h2>
                <p style={{ margin: '3px 0 0 0', fontSize: '12px', color: '#64748b' }}>Interactive practice tasks curated for {selectedSubject}</p>
              </div>
              
              <div style={{ display: 'flex', gap: '6px' }}>
                {studentSubjects.map(sub => (
                  <button key={sub} onClick={() => { setSelectedSubject(sub); setSelectedActivityLesson('All'); }} style={{ ...styles.filterTab, backgroundColor: selectedSubject === sub ? '#145c2e' : '#f1f5f9', color: selectedSubject === sub ? '#fff' : '#475569' }}>
                    {sub}
                  </button>
                ))}
              </div>
            </div>

            {/* LESSON & TYPE FILTER BAR */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '10px', backgroundColor: '#f8fafc', padding: '10px 14px', borderRadius: '10px', border: '1px solid #e2e8f0', marginBottom: '18px' }}>
              
              {/* LESSON SELECTOR */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span style={{ fontSize: '12px', fontWeight: 'bold', color: '#145c2e' }}>📘 Select Lesson:</span>
                <select 
                  value={selectedActivityLesson} 
                  onChange={(e) => setSelectedActivityLesson(e.target.value)}
                  style={{ padding: '5px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '12px', fontWeight: 'bold', backgroundColor: '#fff', color: '#1e293b', cursor: 'pointer' }}
                >
                  <option value="All">All Lessons</option>
                  {availableActivityLessons.map(les => (
                    <option key={les} value={les}>{les}</option>
                  ))}
                </select>
              </div>

              {/* TYPE FILTER BUTTONS */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                {[
                  { type: 'All', label: '📋 All Types' },
                  { type: 'True/False', label: '✅ True / False' },
                  { type: 'MCQ', label: '🔢 MCQ Options' },
                  { type: 'Short Answer', label: '✍️ Short Answer' }
                ].map(item => (
                  <button 
                    key={item.type} 
                    onClick={() => setSelectedActivityType(item.type)}
                    style={{
                      padding: '5px 10px',
                      borderRadius: '16px',
                      border: selectedActivityType === item.type ? '1px solid #145c2e' : '1px solid #cbd5e1',
                      backgroundColor: selectedActivityType === item.type ? '#145c2e' : '#ffffff',
                      color: selectedActivityType === item.type ? '#ffffff' : '#475569',
                      fontSize: '11px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      transition: 'all 0.2s'
                    }}
                  >
                    {item.label}
                  </button>
                ))}
              </div>
            </div>

            {/* ACTIVITIES LIST RENDERER (CLEAN QUESTION 01 NO LESSON DUPLICATION) */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
              {filterActivities(activities).map((act, index) => {
                const type = getActivityType(act);

                return (
                  <div key={act.id} style={styles.activityCardClean}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                      <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#145c2e' }}>
                        Question {String(index + 1).padStart(2, '0')}
                      </span>
                      <div style={{ display: 'flex', gap: '6px' }}>
                        <span style={{ fontSize: '10.5px', backgroundColor: '#ecfdf5', color: '#15803d', border: '1px solid #bbf7d0', padding: '2px 8px', borderRadius: '12px', fontWeight: 'bold' }}>
                          {type}
                        </span>
                        <span style={{ fontSize: '10.5px', backgroundColor: '#f1f5f9', color: '#475569', padding: '2px 8px', borderRadius: '12px', fontWeight: '600' }}>
                          {act.subject || selectedSubject}
                        </span>
                      </div>
                    </div>

                    <p style={{ fontSize: '14px', margin: '0 0 16px 0', color: '#1e293b', fontWeight: '500', lineHeight: '1.5' }}>
                      {formatText(act.question_text)}
                    </p>

                    {/* 1. TRUE / FALSE UI */}
                    {type === 'True/False' && (
                      <div style={{ display: 'flex', gap: '10px', maxWidth: '380px' }}>
                        {['TRUE', 'FALSE'].map((opt) => (
                          <button
                            key={opt}
                            onClick={() => setActivitiesAnswers({ ...activityAnswers, [act.id]: opt })}
                            style={{
                              flex: 1, padding: '9px', borderRadius: '8px',
                              border: activityAnswers[act.id] === opt ? '2px solid #145c2e' : '1px solid #cbd5e1',
                              backgroundColor: activityAnswers[act.id] === opt ? '#d1fae5' : '#ffffff',
                              color: activityAnswers[act.id] === opt ? '#145c2e' : '#475569',
                              fontWeight: 'bold', cursor: 'pointer', fontSize: '12.5px',
                              transition: 'all 0.15s'
                            }}
                          >
                            {opt === 'TRUE' ? '✅ TRUE' : '❌ FALSE'}
                          </button>
                        ))}
                      </div>
                    )}

                    {/* 2. MCQ UI */}
                    {type === 'MCQ' && (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', maxWidth: '650px' }}>
                        {[
                          { key: 'A', text: act.option_a },
                          { key: 'B', text: act.option_b },
                          { key: 'C', text: act.option_c },
                          { key: 'D', text: act.option_d }
                        ].filter(opt => Boolean(opt.text)).map((opt) => (
                          <div 
                            key={opt.key}
                            onClick={() => setActivitiesAnswers({ ...activityAnswers, [act.id]: opt.key })}
                            style={{
                              padding: '9px 12px', borderRadius: '8px',
                              border: activityAnswers[act.id] === opt.key ? '2px solid #145c2e' : '1px solid #e2e8f0',
                              backgroundColor: activityAnswers[act.id] === opt.key ? '#f0fdf4' : '#ffffff',
                              color: activityAnswers[act.id] === opt.key ? '#145c2e' : '#334155',
                              fontSize: '13px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px',
                              fontWeight: activityAnswers[act.id] === opt.key ? 'bold' : 'normal',
                              transition: 'all 0.15s'
                            }}
                          >
                            <span style={{ 
                              backgroundColor: activityAnswers[act.id] === opt.key ? '#145c2e' : '#f1f5f9', 
                              color: activityAnswers[act.id] === opt.key ? '#fff' : '#64748b',
                              borderRadius: '50%', width: '22px', height: '22px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: '11px', fontWeight: 'bold' 
                            }}>
                              {opt.key}
                            </span>
                            {formatText(opt.text)}
                          </div>
                        ))}
                      </div>
                    )}

                    {/* 3. SHORT ANSWER UI */}
                    {type === 'Short Answer' && (
                      <div style={{ maxWidth: '500px' }}>
                        <input 
                          type="text" 
                          placeholder="Type your final answer here..."
                          value={activityAnswers[act.id] || ''}
                          onChange={(e) => setActivitiesAnswers({ ...activityAnswers, [act.id]: e.target.value })}
                          style={{
                            width: '100%',
                            padding: '9px 12px',
                            borderRadius: '8px',
                            border: '1px solid #cbd5e1',
                            outline: 'none',
                            fontSize: '13px',
                            boxSizing: 'border-box'
                          }}
                        />
                      </div>
                    )}
                  </div>
                );
              })}

              {filterActivities(activities).length === 0 && (
                <p style={{ color: '#94a3b8', fontStyle: 'italic', padding: '20px', textAlign: 'center', fontSize: '13px' }}>
                  No activities published for <b>{selectedActivityLesson !== 'All' ? selectedActivityLesson : selectedSubject}</b> yet.
                </p>
              )}
            </div>
          </div>
        )}

        {/* 4. ONLINE FORMAL EXAMS */}
        {activeTab === 'exams' && (
          <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '14px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, fontSize: '17px', color: '#145c2e', fontWeight: 'bold' }}>📝 Online Formal Exams & Evaluations</h2>

            {!activeQuiz ? (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '14px', marginTop: '16px' }}>
                {quizzes.map(q => (
                  <div key={q.id} style={{ border: '1px solid #bbf7d0', padding: '16px', borderRadius: '10px', backgroundColor: '#f0fdf4' }}>
                    <h3 style={{ margin: '0 0 4px 0', color: '#145c2e', fontSize: '15px' }}>{q.title}</h3>
                    <p style={{ margin: '0 0 12px 0', fontSize: '12px', color: '#15803d' }}>Grade: {q.grade} | Duration: {q.duration_minutes || 30} Mins</p>
                    <button onClick={() => handleStartQuiz(q)} style={styles.primaryBtn}>🚀 Start Exam Now</button>
                  </div>
                ))}
                {quizzes.length === 0 && <p style={{ color: '#94a3b8', fontSize: '13px' }}>No active online exams currently available.</p>}
              </div>
            ) : (
              <div style={{ marginTop: '16px', padding: '16px', border: '2px solid #145c2e', borderRadius: '10px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #cbd5e1', paddingBottom: '8px' }}>
                  <h3 style={{ margin: 0, fontSize: '15px' }}>Exam: {activeQuiz.title}</h3>
                  <button onClick={() => setActiveQuiz(null)} style={{ background: '#dc2626', color: 'white', border: 'none', padding: '5px 12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' }}>Exit Exam</button>
                </div>

                {quizResult ? (
                  <div style={{ textAlign: 'center', padding: '24px 0' }}>
                    <h2 style={{ color: '#145c2e', margin: 0 }}>🎉 Exam Submitted!</h2>
                    <h1 style={{ fontSize: '42px', margin: '8px 0', color: '#145c2e' }}>{quizResult.score}%</h1>
                    <p style={{ fontSize: '14px', color: '#475569' }}>{quizResult.message}</p>
                    <button onClick={() => setActiveQuiz(null)} style={{ ...styles.primaryBtn, marginTop: '12px' }}>Back to Exams List</button>
                  </div>
                ) : (
                  <div style={{ marginTop: '16px' }}>
                    {quizQuestions.map((q, idx) => (
                      <div key={q.id} style={{ marginBottom: '14px', padding: '12px', backgroundColor: '#f8fafc', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                        <p style={{ fontWeight: 'bold', margin: '0 0 8px 0', fontSize: '13px' }}>Q{idx + 1}. {formatText(q.question_text)}</p>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                          {['A', 'B', 'C', 'D'].map(opt => (
                            <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: '6px', cursor: 'pointer', fontSize: '12.5px' }}>
                              <input 
                                type="radio" 
                                name={`q_${q.id}`} 
                                value={opt} 
                                checked={userAnswers[q.id] === opt} 
                                onChange={() => setUserAnswers({ ...userAnswers, [q.id]: opt })}
                                style={{ accentColor: '#145c2e' }}
                              />
                              <b>{opt})</b> {formatText(q[`option_${opt.toLowerCase()}`])}
                            </label>
                          ))}
                        </div>
                      </div>
                    ))}
                    <button onClick={handleSubmitExam} style={{ ...styles.primaryBtn, width: '100%', padding: '10px', fontSize: '14px', marginTop: '8px' }}>Submit Exam Answers 📤</button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* 5. TEACHER FEEDBACK FORUM */}
        {activeTab === 'feedback' && (
          <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '14px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, fontSize: '17px', color: '#145c2e', fontWeight: 'bold' }}>💬 Teacher Feedback & Support Forum</h2>
            
            <form onSubmit={handleSendFeedback} style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '12px', backgroundColor: '#f8fafc', padding: '16px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
              <input type="text" placeholder="Subject / Query Title" value={feedbackSubject} onChange={e => setFeedbackSubject(e.target.value)} style={styles.input} />
              <textarea rows="3" placeholder="Type your message or question for the teachers here..." value={feedbackMsg} onChange={e => setFeedbackMsg(e.target.value)} style={{ ...styles.input, resize: 'none' }}></textarea>
              <button type="submit" style={styles.primaryBtn}>📩 Send Message to Teacher</button>
            </form>

            <h3 style={{ marginTop: '20px', color: '#1e293b', fontSize: '14px' }}>Sent Feedback History</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {myFeedbacks.map(f => (
                <div key={f.id} style={{ padding: '10px 12px', border: '1px solid #e2e8f0', borderRadius: '6px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <strong style={{ color: '#145c2e', fontSize: '13px' }}>{f.subject}</strong>
                    <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#475569' }}>{f.message}</p>
                  </div>
                  <span style={{ backgroundColor: '#fef3c7', color: '#d97706', padding: '2px 8px', borderRadius: '10px', fontSize: '10.5px', fontWeight: 'bold' }}>{f.status || 'Pending'}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 6. STUDENT PROFILE SETTINGS TAB */}
        {activeTab === 'settings' && (
          <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '14px', border: '1px solid #e2e8f0', maxWidth: '500px' }}>
            <h2 style={{ marginTop: 0, fontSize: '17px', color: '#145c2e', fontWeight: 'bold' }}>⚙️ Student Profile & Account Settings</h2>
            
            <form onSubmit={(e) => { e.preventDefault(); alert("Profile updated successfully!"); }} style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '16px' }}>
              <div>
                <label style={styles.label}>Full Name:</label>
                <input type="text" value={studentProfile.name} onChange={e => setStudentProfile({ ...studentProfile, name: e.target.value })} style={styles.input} />
              </div>

              <div>
                <label style={styles.label}>Contact Phone Number:</label>
                <input type="text" value={studentProfile.phone} onChange={e => setStudentProfile({ ...studentProfile, phone: e.target.value })} style={styles.input} />
              </div>

              <div>
                <label style={styles.label}>Home Address:</label>
                <input type="text" value={studentProfile.address} onChange={e => setStudentProfile({ ...studentProfile, address: e.target.value })} style={styles.input} />
              </div>

              <div>
                <label style={styles.label}>Update Account Password:</label>
                <input type="password" placeholder="Leave blank to keep current password" value={studentProfile.newPassword} onChange={e => setStudentProfile({ ...studentProfile, newPassword: e.target.value })} style={styles.input} />
              </div>

              <button type="submit" style={{ ...styles.primaryBtn, padding: '9px', fontSize: '13px', marginTop: '8px' }}>💾 Save Profile Changes</button>
            </form>
          </div>
        )}

      </div>
    </div>
  );
}

const styles = {
  navBtn: { padding: '9px 12px', border: 'none', borderRadius: '6px', cursor: 'pointer', textAlign: 'left', fontSize: '12.5px', color: '#fff', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '6px', transition: 'all 0.2s' },
  logoutBtn: { padding: '10px 12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12.5px', textAlign: 'center', marginTop: 'auto' },
  statCard: { backgroundColor: '#fff', padding: '14px', borderRadius: '10px', border: '1px solid #e2e8f0', boxShadow: '0 2px 6px rgba(0,0,0,0.02)' },
  statLabel: { margin: 0, fontSize: '11px', color: '#64748b', fontWeight: 'bold' },
  statValue: { margin: '3px 0 0 0', fontSize: '17px', fontWeight: 'bold' },
  subjectPillBtn: { padding: '5px 14px', borderRadius: '16px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', transition: 'all 0.2s' },
  classBadge: { backgroundColor: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '6px', padding: '4px', fontSize: '10.5px', color: '#145c2e' },
  primaryBtn: { backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '7px 14px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', textDecoration: 'none', display: 'inline-block', textAlign: 'center', fontSize: '12.5px' },
  subjectBadge: { backgroundColor: '#f0fdf4', color: '#145c2e', border: '1px solid #bbf7d0', padding: '2px 8px', borderRadius: '10px', fontSize: '11px', fontWeight: 'bold' },
  materialCard: { backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '12px', padding: '14px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', boxShadow: '0 2px 4px rgba(0,0,0,0.02)' },
  actionBtn: { width: '100%', padding: '8px 10px', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px', textDecoration: 'none', display: 'block', textAlign: 'center' },
  filterTab: { border: 'none', padding: '5px 12px', borderRadius: '16px', fontSize: '11.5px', fontWeight: 'bold', cursor: 'pointer', transition: 'all 0.2s' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  videoModal: { backgroundColor: 'white', padding: '16px', borderRadius: '14px', width: '640px', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' },
  closeBtn: { background: '#dc2626', color: 'white', border: 'none', padding: '5px 10px', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold', fontSize: '11.5px' },
  input: { padding: '8px 11px', borderRadius: '6px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '12.5px', backgroundColor: '#fff', width: '100%', boxSizing: 'border-box' },
  label: { fontSize: '12px', fontWeight: 'bold', color: '#334155', marginBottom: '3px', display: 'block' },
  activityCardClean: {
    backgroundColor: '#ffffff',
    border: '1px solid #e2e8f0',
    borderLeft: '4px solid #145c2e',
    borderRadius: '10px',
    padding: '16px',
    boxShadow: '0 2px 6px rgba(0,0,0,0.02)'
  }
};
